Bin‑search in verse:

# 1. Midpoint rests in the hush
# 2. Compare, decide, recurse, and rush

def bsearch(arr, target, lo=0, hi=None):
    if hi is None: hi=len(arr)
    if lo>=hi: return None
    mid=(lo+hi)//2
    if arr[mid]==target: return mid
    return bsearch(arr, target, lo, mid) if target< arr[mid] else bsearch(arr, target, mid+1, hi)

